// @ts-check
// n8n Code node "Validate lead" (mode: run once for all items).
// Checks the shared secret and turns the raw form post into a clean lead, or into the HTTP
// response that rejects it. Everything in the request comes from the internet: field values are
// stripped of HTML and control characters, cut to fixed lengths, and only known fields are kept.

/**
 * @typedef {object} WebhookRequest Webhook node output.
 * @property {Record<string, string | undefined>} [headers] header names in lower case
 * @property {Record<string, unknown>} [query]
 * @property {unknown} [body] parsed JSON or form fields
 *
 * @typedef {'email' | 'name' | 'firstName' | 'lastName' | 'company' | 'phone' | 'website' | 'message'} Field
 *
 * @typedef {object} Settings
 * @property {string} webhookSecret
 * @property {string} secretHeader
 * @property {string} [secretQueryParam] '' disables the query parameter
 * @property {string} honeypotField
 * @property {Record<Field, string[]>} fields accepted form field names per lead field
 * @property {Field[]} requiredFields
 *
 * @typedef {object} Lead
 * @property {string} email lower case
 * @property {string} firstName
 * @property {string} lastName
 * @property {string} company
 * @property {string} phone
 * @property {string} website
 * @property {string} message
 * @property {boolean} truncated a field was longer than its limit
 * @property {string} receivedAt ISO timestamp
 *
 * @typedef {'accepted' | 'bot' | 'invalid' | 'unauthorized' | 'misconfigured'} Status
 */

/** @type {Record<Field, number>} */
const MAX_CHARS = {
  email: 254,
  name: 200,
  firstName: 100,
  lastName: 100,
  company: 200,
  phone: 40,
  website: 200,
  message: 5000,
};
const MIN_SECRET_CHARS = 16;
const EMAIL = /^[^\s@<>()[\]\\,;:"]{1,64}@(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i;
const PHONE = /^[0-9+()./\s-]{5,40}$/;
const WEBSITE = /^(https?:\/\/)?([a-z0-9-]+\.)+[a-z]{2,63}(:\d+)?(\/\S*)?$/i;

/**
 * Compares in time that depends only on the expected secret's length, so response times do not
 * reveal how many leading characters of a guess were right.
 * @param {string} given
 * @param {string} expected
 */
function sameSecret(given, expected) {
  let diff = given.length ^ expected.length;
  for (let i = 0; i < expected.length; i++) diff |= given.charCodeAt(i % (given.length || 1)) ^ expected.charCodeAt(i);
  return diff === 0;
}

/**
 * @param {unknown} value
 * @param {boolean} multiline
 */
function clean(value, multiline) {
  const text = String(value)
    .replace(/<(script|style)\b[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\r\n?/g, '\n')
    // eslint-disable-next-line no-control-regex
    .replace(/[\u0000-\u0009\u000b-\u001f\u007f\u200b-\u200f\u2028\u2029\ufeff]/g, ' ');
  if (!multiline) return text.replace(/\s+/g, ' ').trim();
  return text
    .split('\n')
    .map((line) => line.replace(/\s+/g, ' ').trim())
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * @param {Status} status
 * @param {number} httpStatus
 * @param {Record<string, unknown>} body
 * @param {Partial<{ lead: Lead, errors: string[] }>} [extra]
 */
const outcome = (status, httpStatus, body, extra = {}) => ({
  status,
  response: { status: httpStatus, body },
  errors: extra.errors ?? [],
  lead: extra.lead ?? null,
});

/** @param {string[]} errors */
const invalid = (errors) => outcome('invalid', 400, { ok: false, errors }, { errors });

/**
 * @param {WebhookRequest} req
 * @param {Settings} settings
 */
function validate(req, settings) {
  const secret = String(settings.webhookSecret ?? '');
  if (secret.length < MIN_SECRET_CHARS || secret.startsWith('REPLACE'))
    return outcome(
      'misconfigured',
      500,
      { ok: false, error: 'server not configured' },
      {
        errors: [`webhookSecret in Settings must be set to a random string of at least ${MIN_SECRET_CHARS} characters`],
      },
    );
  const header = req.headers?.[settings.secretHeader.toLowerCase()];
  const query = settings.secretQueryParam ? req.query?.[settings.secretQueryParam] : undefined;
  const given = typeof header === 'string' ? header : typeof query === 'string' ? query : '';
  if (!sameSecret(given, secret)) return outcome('unauthorized', 401, { ok: false, error: 'unauthorized' });

  const body = req.body;
  if (!body || typeof body !== 'object' || Array.isArray(body))
    return invalid(['body must be a JSON object or form fields']);

  // Form tools differ in field names and capitalisation, so fields are matched case-insensitively
  // against the names configured in Settings.
  /** @type {Map<string, unknown>} */
  const byKey = new Map(Object.entries(body).map(([k, v]) => [k.trim().toLowerCase(), v]));

  // Bots fill every field; people never see the hidden one. They get the same answer as a real
  // submission so they cannot tell the difference.
  const trap = byKey.get(settings.honeypotField.toLowerCase());
  if (trap !== undefined && trap !== null && String(trap).trim() !== '') return outcome('bot', 202, { ok: true });

  const errors = [];
  let truncated = false;
  /** @type {Record<Field, string>} */
  const raw = { email: '', name: '', firstName: '', lastName: '', company: '', phone: '', website: '', message: '' };
  for (const field of /** @type {Field[]} */ (Object.keys(raw))) {
    const key = (settings.fields[field] ?? []).map((k) => k.toLowerCase()).find((k) => byKey.has(k));
    if (key === undefined) continue;
    const value = byKey.get(key);
    if (value === null || value === undefined) continue;
    if (!['string', 'number'].includes(typeof value)) {
      errors.push(`${field} must be text`);
      continue;
    }
    const text = clean(value, field === 'message');
    if (text.length > MAX_CHARS[field]) truncated = true;
    raw[field] = text.slice(0, MAX_CHARS[field]).trim();
  }

  for (const field of settings.requiredFields)
    if (!raw[field] && !errors.includes(`${field} must be text`)) errors.push(`${field} is required`);
  const email = raw.email.toLowerCase();
  if (email && (!EMAIL.test(email) || /^\.|\.\.|\.@/.test(email))) errors.push('email is not a valid address');
  if (raw.phone && !PHONE.test(raw.phone)) errors.push('phone may only contain digits, spaces and + ( ) . / -');
  if (raw.website && !WEBSITE.test(raw.website)) errors.push('website is not a valid domain or URL');
  if (errors.length) return invalid(errors);

  let { firstName, lastName } = raw;
  if (!firstName && !lastName && raw.name) {
    const [first, ...rest] = raw.name.split(' ');
    firstName = first.slice(0, MAX_CHARS.firstName);
    lastName = rest.join(' ').slice(0, MAX_CHARS.lastName);
  }

  /** @type {Lead} */
  const lead = {
    email,
    firstName,
    lastName,
    company: raw.company,
    phone: raw.phone,
    website: raw.website,
    message: raw.message,
    truncated,
    receivedAt: new Date().toISOString(),
  };
  return outcome('accepted', 202, { ok: true }, { lead });
}

const settings = /** @type {Settings} */ ($('Settings').first().json);

// @ts-expect-error n8n runs Code node sources as a function body, so the top-level return is valid there.
return $('Lead webhook')
  .all()
  .map((item, i) => ({ json: validate(/** @type {WebhookRequest} */ (item.json), settings), pairedItem: { item: i } }));

// @ts-check
// n8n Code node "Prepare qualification" (mode: run once for all items).
// Builds the request to Claude for each accepted lead. The lead goes into the request inside
// <lead> tags as data, and any tag that could close that block early is removed from it first.

/**
 * @typedef {import('./validate-lead.js').Lead} Lead
 *
 * @typedef {{ model: string, systemPrompt: string, businessDescription: string }} Settings
 */

const TAGS = /<\/?\s*(lead|name|email|company|website|message|business)\b[^>]*>/gi;

/** @param {unknown} s */
const stripDelimiters = (s) => String(s ?? '').replace(TAGS, ' ');

const settings = /** @type {Settings} */ ($('Settings').first().json);

// @ts-expect-error n8n runs Code node sources as a function body, so the top-level return is valid there.
return $input.all().map((item, i) => {
  const { lead } = /** @type {{ lead: Lead }} */ (item.json);

  const userContent = [
    '<lead>',
    `<name>${stripDelimiters(`${lead.firstName} ${lead.lastName}`.trim())}</name>`,
    `<email>${stripDelimiters(lead.email)}</email>`,
    `<company>${stripDelimiters(lead.company)}</company>`,
    `<website>${stripDelimiters(lead.website)}</website>`,
    `<message>${stripDelimiters(lead.message)}</message>`,
    '</lead>',
    '',
    'Qualify the lead above. Reply with the JSON object only.',
  ].join('\n');

  return {
    json: {
      lead,
      request: {
        model: settings.model,
        max_tokens: 500,
        // Haiku 5.5 thinks by default and thinking tokens count against max_tokens; scoring one
        // form does not need it.
        thinking: { type: 'disabled' },
        system: `${settings.systemPrompt}\n\nAbout the business:\n${settings.businessDescription}`,
        messages: [{ role: 'user', content: userContent }],
      },
    },
    pairedItem: { item: i },
  };
});

// @ts-check
// n8n Code node "Parse qualification" (mode: run once for all items).
// Turns Claude's reply into a validated qualification. A failed call or a malformed reply sets
// needs_review instead of dropping the lead, and leaves score and intent empty.
// The reply is not trusted either: the form it was generated from may contain instructions aimed
// at the model, so every field is checked or clamped here, whatever the model says.

/**
 * @typedef {import('./validate-lead.js').Lead} Lead
 *
 * @typedef {object} ClaudeResponse Ask Claude output: a Messages API response, or { error } after failed retries.
 * @property {{ type: string, text?: string }[]} [content]
 * @property {string} [stop_reason]
 * @property {string | { message?: string }} [error]
 *
 * @typedef {object} Qualification
 * @property {number | null} fit_score 0-100, null when needs_review
 * @property {string} intent one of INTENTS, '' when needs_review
 * @property {string} budget as stated in the form, or ''
 * @property {string} timeline as stated in the form, or ''
 * @property {string} summary
 * @property {string} next_step
 */

const INTENTS = ['buy', 'info', 'support', 'spam', 'job', 'partner'];
const MAX = { budget: 100, timeline: 100, summary: 300, next_step: 200 };

/** @param {string} text */
function extractJson(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('no JSON object in model reply');
  return JSON.parse(text.slice(start, end + 1));
}

/** @param {NonNullable<ClaudeResponse['error']>} error */
function apiErrorMessage(error) {
  return `API error: ${typeof error === 'string' ? error : (error.message ?? JSON.stringify(error))}`;
}

/**
 * @param {unknown} value
 * @param {number} max
 */
function text(value, max) {
  if (typeof value !== 'string') return '';
  return (
    value
      // eslint-disable-next-line no-control-regex
      .replace(/[\u0000-\u001f\u007f]+/g, ' ')
      .trim()
      .slice(0, max)
  );
}

/**
 * True if every number in the model's value also appears in what the visitor wrote, so a budget
 * the model made up or "corrected" is dropped instead of stored.
 * @param {string} value
 * @param {string} source
 */
function numbersFrom(value, source) {
  const digits = (/** @type {string} */ s) => (s.match(/\d+/g) ?? []).map((n) => n.replace(/^0+(?=\d)/, ''));
  const known = new Set(digits(source.replace(/(\d)[.,'\s](?=\d{3}\b)/g, '$1')));
  return digits(value.replace(/(\d)[.,'\s](?=\d{3}\b)/g, '$1')).every((n) => known.has(n));
}

/**
 * @param {ClaudeResponse} res
 * @param {Lead} lead
 * @returns {{ qualification: Qualification, problems: string[] }}
 */
function qualify(res, lead) {
  // Ask Claude continues on error, so a failed request (after its retries) arrives here as { error }.
  if (res.error) throw new Error(apiErrorMessage(res.error));
  if (res.stop_reason === 'max_tokens') throw new Error('model reply cut off at max_tokens');
  if (res.stop_reason === 'refusal') throw new Error('model declined to answer');
  const raw = extractJson(res.content?.map((c) => c.text ?? '').join('') ?? '');
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('model reply is not a JSON object');

  const problems = [];
  const scoreOk = Number.isInteger(raw.fit_score) && raw.fit_score >= 0 && raw.fit_score <= 100;
  if (!scoreOk) problems.push(`fit_score ${JSON.stringify(raw.fit_score)}`);
  const intentOk = INTENTS.includes(raw.intent);
  if (!intentOk) problems.push(`intent ${JSON.stringify(raw.intent)}`);
  const summary = text(raw.summary, MAX.summary);
  if (!summary) problems.push('summary missing');

  const source = `${lead.message} ${lead.company}`;
  const budget = text(raw.budget, MAX.budget);
  const timeline = text(raw.timeline, MAX.timeline);
  const valid = problems.length === 0;
  return {
    problems,
    qualification: {
      fit_score: valid ? (raw.intent === 'spam' ? 0 : raw.fit_score) : null,
      intent: valid ? raw.intent : '',
      budget: budget && numbersFrom(budget, source) ? budget : '',
      timeline: timeline && numbersFrom(timeline, source) ? timeline : '',
      summary,
      next_step: text(raw.next_step, MAX.next_step),
    },
  };
}

const settings = /** @type {{ hotScore: number }} */ ($('Settings').first().json);
const prepared = $('Prepare qualification').all();

// @ts-expect-error n8n runs Code node sources as a function body, so the top-level return is valid there.
return $input.all().map((item, i) => {
  const { lead } = /** @type {{ lead: Lead }} */ (prepared[i].json);
  /** @type {Qualification} */
  let qualification;
  let error = '';
  try {
    const result = qualify(/** @type {ClaudeResponse} */ (item.json), lead);
    qualification = result.qualification;
    if (result.problems.length) error = `invalid: ${result.problems.join(', ')}`;
  } catch (err) {
    qualification = { fit_score: null, intent: '', budget: '', timeline: '', summary: '', next_step: '' };
    error = err instanceof Error ? err.message : String(err);
  }
  const needsReview = error !== '';
  const hot = !needsReview && qualification.intent === 'buy' && Number(qualification.fit_score) >= settings.hotScore;
  return {
    json: { lead, qualification, hot, needs_review: needsReview, error },
    pairedItem: { item: i },
  };
});
